// Recursive fractal patterns responsive to metrics

class FractalMode {
    constructor() {
        this.maxDepth = 8;
        this.angle = 0;
    }

    initialize() {
        // No initialization needed
    }

    /**
     * Update fractal parameters based on metrics.
     */
    update(metrics) {
        this.sentiment = (metrics.customer_sentiment + 1) / 2;
        this.velocity = metrics.sales_velocity / 100;
        this.latency = metrics.supply_chain_latency / 1000;
        this.angle += this.velocity * 0.02;
    }

    /**
     * Render fractal tree recursively.
     * 
     * THREE-BULLET EDUCATION:
     * 1. Recursion draws self-similar patterns (tree branches)
     * 2. Sentiment controls branch angle (more positive = sharper angles)
     * 3. Velocity controls branch length (faster = longer branches)
     */
    display() {
        push();
        translate(width / 2, height);
        rotate(this.angle);

        this.drawBranch(
            120,                                    // Initial branch length
            map(this.sentiment, 0, 1, 15, 40),     // Branch angle (degrees)
            0                                       // Current recursion depth
        );

        pop();
    }

    /**
     * Recursive function to draw fractal branches.
     */
    drawBranch(length, angle, depth) {
        if (depth > this.maxDepth || length < 2) return;

        // Calculate branch color based on depth and sentiment
        const hue = map(depth, 0, this.maxDepth, 30, 200);
        const alpha = map(depth, 0, this.maxDepth, 255, 30);
        const branchColor = hslToRgb(hue, 100, 50, alpha);

        // Draw branch line
        stroke(branchColor);
        strokeWeight(map(depth, 0, this.maxDepth, 4, 0.5));
        line(0, 0, 0, -length);

        // Recursive calls for left and right branches
        push();
        translate(0, -length);
        rotate(radians(angle));
        this.drawBranch(length * 0.67, angle, depth + 1);
        pop();

        push();
        translate(0, -length);
        rotate(radians(-angle));
        this.drawBranch(length * 0.67, angle, depth + 1);
        pop();
    }
}

