// Capture and replay visualization sessions for analysis

class DataRecorder {
    constructor() {
        this.isRecording = false;
        this.recordedFrames = [];
        this.playbackIndex = 0;
        this.isPlayingBack = false;
        this.playbackSpeed = 1.0;
    }

    /**
     * Start recording metrics and particle state.
     * 
     * THREE-BULLET EDUCATION:
     * 1. Records metric snapshots every frame (60 fps = high fidelity)
     * 2. Stores particle positions for exact replay (deterministic playback)
     * 3. Compression possible: only record when data changes significantly
     */
    startRecording() {
        this.recordedFrames = [];
        this.isRecording = true;
        console.log('🔴 Recording started');
    }

    /**
     * Add frame data to recording buffer.
     */
    recordFrame(metrics, particleData) {
        if (!this.isRecording) return;

        this.recordedFrames.push({
            timestamp: frameCount,
            metrics: { ...metrics },
            particles: particleData.map(p => ({
                x: p.x,
                y: p.y,
                vx: p.vx,
                vy: p.vy,
                hue: p.hue
            }))
        });
    }

    /**
     * Stop recording and return captured data.
     */
    stopRecording() {
        this.isRecording = false;
        console.log(`⏹️ Recording stopped (${this.recordedFrames.length} frames)`);
        return this.recordedFrames;
    }

    /**
     * Export recorded data as JSON file.
     */
    exportRecording(filename = 'kinetic-recording.json') {
        const dataStr = JSON.stringify(this.recordedFrames, null, 2);
        const blob = new Blob([dataStr], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = filename;
        link.click();
        console.log('📥 Recording exported');
    }

    /**
     * Import recorded data from JSON file.
     */
    importRecording(file) {
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                this.recordedFrames = JSON.parse(e.target.result);
                console.log(`📤 Recording imported (${this.recordedFrames.length} frames)`);
            } catch (error) {
                console.error('Failed to import recording:', error);
            }
        };
        reader.readAsText(file);
    }

    /**
     * Start playback of recorded session.
     */
    startPlayback() {
        this.isPlayingBack = true;
        this.playbackIndex = 0;
        console.log('▶️ Playback started');
    }

    /**
     * Get next frame in playback sequence.
     */
    getPlaybackFrame() {
        if (!this.isPlayingBack || this.recordedFrames.length === 0) return null;

        const frame = this.recordedFrames[Math.floor(this.playbackIndex)];
        this.playbackIndex += this.playbackSpeed;

        if (this.playbackIndex >= this.recordedFrames.length) {
            this.stopPlayback();
        }

        return frame;
    }

    /**
     * Stop playback.
     */
    stopPlayback() {
        this.isPlayingBack = false;
        console.log('⏹️ Playback stopped');
    }

    /**
     * Set playback speed (1.0 = normal, 2.0 = 2x speed, 0.5 = half speed).
     */
    setPlaybackSpeed(speed) {
        this.playbackSpeed = constrain(speed, 0.1, 5.0);
        console.log(`⏱️ Playback speed: ${this.playbackSpeed}x`);
    }
}

