// Extensible behavior system for custom particle behaviors

class PluginSystem {
    constructor() {
        this.plugins = [];
        this.hooks = {
            onParticleUpdate: [],
            onMetricsChange: [],
            onFrameRender: []
        };
    }

    /**
     * Register a new plugin.
     * Plugins extend particle behavior without modifying core code.
     * 
     * THREE-BULLET EDUCATION:
     * 1. Plugins follow observer pattern (loosely coupled)
     * 2. Multiple plugins can hook same events (composition over inheritance)
     * 3. Plugins enable community extensions (user-created behaviors)
     */
    register(plugin) {
        if (!plugin.name) {
            console.warn('Plugin must have a name property');
            return;
        }

        this.plugins.push(plugin);

        // Register hooks if plugin defines them
        if (plugin.onParticleUpdate) {
            this.hooks.onParticleUpdate.push(plugin.onParticleUpdate.bind(plugin));
        }
        if (plugin.onMetricsChange) {
            this.hooks.onMetricsChange.push(plugin.onMetricsChange.bind(plugin));
        }
        if (plugin.onFrameRender) {
            this.hooks.onFrameRender.push(plugin.onFrameRender.bind(plugin));
        }

        console.log(`✅ Plugin registered: ${plugin.name}`);
    }

    /**
     * Execute all callbacks for a specific hook.
     */
    executeHook(hookName, ...args) {
        if (this.hooks[hookName]) {
            this.hooks[hookName].forEach(callback => callback(...args));
        }
    }

    /**
     * Unregister a plugin.
     */
    unregister(pluginName) {
        this.plugins = this.plugins.filter(p => p.name !== pluginName);
        console.log(`❌ Plugin unregistered: ${pluginName}`);
    }
}

