// Demonstrates how to create custom plugins

class TrailPlugin {
    constructor() {
        this.name = 'TrailPlugin';
        this.trails = new Map(); // Store trails for each particle
        this.trailLength = 20;
    }

    /**
     * Hook called when particles update.
     */
    onParticleUpdate(particle, metrics) {
        const particleId = particle.x + '-' + particle.y; // Simple ID

        if (!this.trails.has(particleId)) {
            this.trails.set(particleId, []);
        }

        const trail = this.trails.get(particleId);
        trail.push({ x: particle.x, y: particle.y });

        if (trail.length > this.trailLength) {
            trail.shift();
        }
    }

    /**
     * Hook called during frame rendering.
     */
    onFrameRender() {
        // Draw all trails
        this.trails.forEach(trail => {
            for (let i = 0; i < trail.length - 1; i++) {
                const alpha = map(i, 0, trail.length, 0, 100);
                stroke(0, 212, 255, alpha);
                strokeWeight(1);
                line(trail[i].x, trail[i].y, trail[i + 1].x, trail[i + 1].y);
            }
        });
    }
}

