class ForceFieldPlugin {
    constructor() {
        this.name = 'ForceFieldPlugin';
        this.forceFields = [];
    }

    /**
     * Add a custom force field.
     */
    addField(x, y, radius, strength) {
        this.forceFields.push({ x, y, radius, strength });
    }

    /**
     * Apply force fields to particles.
     */
    onParticleUpdate(particle) {
        this.forceFields.forEach(field => {
            const dist = distance(particle.x, particle.y, field.x, field.y);
            if (dist < field.radius) {
                const force = (field.radius - dist) / field.radius * field.strength;
                const angle = atan2(field.y - particle.y, field.x - particle.x);
                particle.ax += cos(angle) * force;
                particle.ay += sin(angle) * force;
            }
        });
    }
}

