/**
 * Handle parameter changes from control panel.
 */
function handleParameterChange(key, value) {
    switch (key) {
        case 'particleCount':
            particleSwarm.adjustParticleCount(value);
            break;
        case 'dataSmoothing':
            dataGenerator.smoothing = value;
            break;
        case 'audioSensitivity':
            audioEngine.audioSensitivity = value;
            break;
        case 'motionBlur':
            // Will be used in draw loop
            break;
    }
}

/**
 * p5.js draw() - Main render loop with advanced features.
 */
function draw() {
    // Step 1: Update data generators
    dataGenerator.update();
    audioEngine.update();
    let metrics = dataGenerator.getMetrics();

    // Step 2: Apply audio influence to metrics
    if (audioEngine.isActive) {
        const audioInfluence = audioEngine.getEnergy();
        metrics.sales_velocity = map(
            audioEngine.frequencyBands.mid,
            0, 1,
            metrics.sales_velocity * 0.7,
            100
        );
    }

    // Step 3: Update particle system
    particleSwarm.update(metrics);

    // Step 4: Execute plugin hooks
    pluginSystem.executeHook('onMetricsChange', metrics);

    // Step 5: Render background with adaptive motion blur
    const motionBlurAmount = controlPanel.getParameter('motionBlur') || 20;
    background(10, 14, 39, motionBlurAmount);

    // Step 6: Render particles
    particleSwarm.display();

    // Step 7: Execute render plugins
    pluginSystem.executeHook('onFrameRender');

    // Step 8: Record data if active
    if (dataRecorder.isRecording) {
        dataRecorder.recordFrame(metrics, particleSwarm.getParticleData());
    }

    // Step 9: Update dashboard
    DashboardController.updateMetrics(metrics);
    fpsTracker = frameRate();
    DashboardController.updateFPS(fpsTracker);
}

/**
 * p5.js windowResized() - Responsive canvas.
 */
function windowResized() {
    const container = document.getElementById('canvas-container');
    if (container) {
        resizeCanvas(container.clientWidth, container.clientHeight);
    }
}

/**
 * Keyboard shortcuts for advanced features.
 */
function keyPressed() {
    if (keyCode === 82) {  // 'R' key - Record
        if (dataRecorder.isRecording) {
            const data = dataRecorder.stopRecording();
            dataRecorder.exportRecording(`kinetic-${Date.now()}.json`);
        } else {
            dataRecorder.startRecording();
        }
    }

    if (keyCode === 80) {  // 'P' key - Playback
        if (dataRecorder.isPlayingBack) {
            dataRecorder.stopPlayback();
        } else {
            dataRecorder.startPlayback();
        }
    }

    if (keyCode === 65) {  // 'A' key - Toggle Audio
        if (audioEngine.isActive) {
            audioEngine.disable();
        } else {
            audioEngine.initialize();
        }
    }

    if (keyCode === 67) {  // 'C' key - Toggle Controls
        controlPanel.toggle();
    }

    return false; // Prevent default browser behavior
}

