```javascript
// ============================================================================
// MICROSOFT FABRIC REAL-TIME CONNECTOR
// Handles authentication, streaming, and data transformation
// ============================================================================

class FabricAuthenticator {
    /**
     * Handle OAuth 2.0 authentication flow.
     * Acquires access token for Fabric API calls.
     * 
     * THREE-BULLET EDUCATION:
     * 1. OAuth 2.0 prevents storing credentials in frontend code
     * 2. Access tokens are short-lived (1 hour) for security
     * 3. Refresh tokens allow silent re-authentication without user interaction
     */
    constructor(config) {
        this.tenantId = config.tenantId;
        this.clientId = config.clientId;
        this.clientSecret = config.clientSecret; // NEVER expose in frontend!
        this.accessToken = null;
        this.tokenExpiry = null;
        this.refreshToken = null;
        this.redirectUri = config.redirectUri || window.location.origin + '/callback';
    }

    /**
     * Get valid access token (acquire or refresh).
     */
    async getAccessToken() {
        // If token still valid, return it
        if (this.accessToken && this.tokenExpiry && Date.now() < this.tokenExpiry - 5000) {
            return this.accessToken;
        }

        // If refresh token exists, use it (silent refresh)
        if (this.refreshToken) {
            return await this.refreshAccessToken();
        }

        // Otherwise, perform full OAuth flow
        return await this.acquireAccessToken();
    }

    /**
     * Perform full OAuth 2.0 authorization code flow.
     */
    async acquireAccessToken() {
        // Step 1: Generate authorization URL
        const authParams = new URLSearchParams({
            client_id: this.clientId,
            response_type: 'code',
            scope: 'https://graph.microsoft.com/.default',
            redirect_uri: this.redirectUri,
            prompt: 'select_account'
        });

        const authUrl = `https://login.microsoftonline.com/${this.tenantId}/oauth2/v2.0/authorize?${authParams}`;

        // Step 2: Redirect user to login (or open popup)
        console.log('🔐 Redirecting to Microsoft login...');
        window.location.href = authUrl;

        // Step 3: Handle callback (on redirect_uri)
        // This should be handled by a backend server or callback page
    }

    /**
     * Handle OAuth callback and exchange auth code for token.
     * IMPORTANT: This should run on your backend server, NOT in browser!
     */
    async handleAuthCallback(authCode) {
        try {
            const tokenResponse = await fetch(
                `https://login.microsoftonline.com/${this.tenantId}/oauth2/v2.0/token`,
                {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                    body: new URLSearchParams({
                        client_id: this.clientId,
                        client_secret: this.clientSecret,
                        code: authCode,
                        redirect_uri: this.redirectUri,
                        grant_type: 'authorization_code',
                        scope: 'https://graph.microsoft.com/.default'
                    })
                }
            );

            const data = await tokenResponse.json();
            this.accessToken = data.access_token;
            this.refreshToken = data.refresh_token;
            this.tokenExpiry = Date.now() + (data.expires_in * 1000);

            console.log('✅ Authentication successful');
            return this.accessToken;
        } catch (error) {
            console.error('❌ Authentication failed:', error);
            throw error;
        }
    }

    /**
     * Refresh access token silently.
     */
    async refreshAccessToken() {
        try {
            const tokenResponse = await fetch(
                `https://login.microsoftonline.com/${this.tenantId}/oauth2/v2.0/token`,
                {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                    body: new URLSearchParams({
                        client_id: this.clientId,
                        client_secret: this.clientSecret,
                        refresh_token: this.refreshToken,
                        grant_type: 'refresh_token',
                        scope: 'https://graph.microsoft.com/.default'
                    })
                }
            );

            const data = await tokenResponse.json();
            this.accessToken = data.access_token;
            this.tokenExpiry = Date.now() + (data.expires_in * 1000);

            console.log('🔄 Token refreshed');
            return this.accessToken;
        } catch (error) {
            console.error('⚠️ Token refresh failed:', error);
            // Force re-authentication
            return await this.acquireAccessToken();
        }
    }
}

// ============================================================================
// FABRIC REAL-TIME STREAM CONNECTOR
// ============================================================================

class FabricRealtimeConnector {
    /**
     * Connect to Fabric real-time metrics stream via WebSocket.
     * 
     * THREE-BULLET EDUCATION:
     * 1. WebSocket provides persistent bidirectional connection
     * 2. Heartbeat pings keep connection alive through firewalls
     * 3. Event-driven architecture handles async data updates
     */
    constructor(authenticator, config = {}) {
        this.authenticator = authenticator;
        this.websocketUrl = config.websocketUrl || 'wss://fabric-stream.microsoft.com/v1/metrics';
        this.workspaceId = config.workspaceId;
        this.websocket = null;
        this.isConnected = false;
        this.reconnectAttempts = 0;
        this.maxReconnectAttempts = config.maxReconnectAttempts || 10;
        this.reconnectDelay = config.reconnectDelay || 3000;
        this.heartbeatInterval = null;
        this.subscribers = [];
        this.messageBuffer = []; // Queue messages while reconnecting
        this.config = config;
    }

    /**
     * Establish WebSocket connection.
     */
    async connect() {
        try {
            // Get fresh access token
            const token = await this.authenticator.getAccessToken();

            return new Promise((resolve, reject) => {
                this.websocket = new WebSocket(
                    `${this.websocketUrl}?workspace=${this.workspaceId}`,
                    ['craft.websocket.fabric']
                );

                // Set authorization header (non-standard but supported by Fabric API)
                this.websocket.onopen = async () => {
                    console.log('✅ WebSocket connected to Fabric API');

                    // Send authentication frame
                    this.websocket.send(JSON.stringify({
                        type: 'authorize',
                        token: token
                    }));

                    // Send subscription request
                    this.websocket.send(JSON.stringify({
                        type: 'subscribe',
                        metrics: [
                            'sales_velocity',
                            'customer_sentiment',
                            'supply_chain_latency'
                        ],
                        interval: 1000 // Update every 1 second
                    }));

                    this.isConnected = true;
                    this.reconnectAttempts = 0;

                    // Start heartbeat to keep connection alive
                    this.startHeartbeat();

                    // Flush buffered messages
                    this.flushMessageBuffer();

                    resolve();
                };

                this.websocket.onmessage = (event) => {
                    try {
                        const message = JSON.parse(event.data);
                        this.handleMessage(message);
                    } catch (error) {
                        console.error('Failed to parse WebSocket message:', error);
                    }
                };

                this.websocket.onerror = (error) => {
                    console.error('❌ WebSocket error:', error);
                    this.isConnected = false;
                    reject(error);
                };

                this.websocket.onclose = () => {
                    console.log('⚠️ WebSocket disconnected');
                    this.isConnected = false;
                    this.stopHeartbeat();
                    this.attemptReconnect();
                };

                // Connection timeout (30 seconds)
                setTimeout(() => {
                    if (!this.isConnected) {
                        reject(new Error('Connection timeout'));
                    }
                }, 30000);
            });
        } catch (error) {
            console.error('Connection error:', error);
            throw error;
        }
    }

    /**
     * Handle incoming WebSocket messages from Fabric API.
     */
    handleMessage(message) {
        switch (message.type) {
            case 'metric_update':
                this.notifySubscribers(message.data);
                break;

            case 'heartbeat_ack':
                // Keep-alive acknowledgment
                break;

            case 'error':
                console.error('🚨 Fabric API error:', message.error);
                break;

            case 'authorized':
                console.log('🔐 Authorization successful');
                break;

            default:
                console.log('Unknown message type:', message.type);
        }
    }

    /**
     * Send periodic heartbeat to keep connection alive.
     */
    startHeartbeat() {
        this.heartbeatInterval = setInterval(() => {
            if (this.isConnected && this.websocket) {
                this.websocket.send(JSON.stringify({ type: 'heartbeat' }));
            }
        }, 30000); // Every 30 seconds
    }

    /**
     * Stop heartbeat.
     */
    stopHeartbeat() {
        if (this.heartbeatInterval) {
            clearInterval(this.heartbeatInterval);
        }
    }

    /**
     * Attempt reconnection with exponential backoff.
     */
    attemptReconnect() {
        if (this.reconnectAttempts < this.maxReconnectAttempts) {
            this.reconnectAttempts++;
            const delay = this.reconnectDelay * Math.pow(1.5, this.reconnectAttempts - 1);
            console.log(`🔄 Reconnecting in ${Math.round(delay / 1000)}s (attempt ${this.reconnectAttempts}/${this.maxReconnectAttempts})`);
            setTimeout(() => this.connect().catch(() => {}), delay);
        } else {
            console.error('❌ Max reconnection attempts reached');
        }
    }

    /**
     * Subscribe to metric updates.
     */
    subscribe(callback) {
        this.subscribers.push(callback);
    }

    /**
     * Notify all subscribers of new data.
     */
    notifySubscribers(data) {
        this.subscribers.forEach(callback => {
            try {
                callback(data);
            } catch (error) {
                console.error('Subscriber callback error:', error);
            }
        });
    }

    /**
     * Send command to Fabric API (e.g., request specific metric).
     */
    send(command) {
        if (this.isConnected && this.websocket) {
            this.websocket.send(JSON.stringify(command));
        } else {
            // Buffer message for later
            this.messageBuffer.push(command);
            console.log('📤 Message buffered (connection pending)');
        }
    }

    /**
     * Flush buffered messages after reconnection.
     */
    flushMessageBuffer() {
        while (this.messageBuffer.length > 0) {
            const message = this.messageBuffer.shift();
            this.send(message);
        }
    }

    /**
     * Graceful disconnect.
     */
    disconnect() {
        this.stopHeartbeat();
        if (this.websocket) {
            this.websocket.close();
        }
        this.isConnected = false;
        console.log('🔌 Disconnected from Fabric API');
    }
}

// ============================================================================
// DATA TRANSFORMATION PIPELINE
// ============================================================================

class DataTransformationPipeline {
    /**
     * Transform Fabric raw metrics into visualization-ready data.
     * 
     * THREE-BULLET EDUCATION:
     * 1. Normalization ensures metrics stay within expected ranges
     * 2. Smoothing prevents jarring visual jumps
     * 3. Aggregation combines multiple data sources into cohesive metrics
     */
    constructor() {
        this.smoothingFactors = {
            sales_velocity: 0.08,
            customer_sentiment: 0.08,
            supply_chain_latency: 0.08
        };

        this.normalizedMetrics = {
            sales_velocity: 0,
            customer_sentiment: 0,
            supply_chain_latency: 0
        };

        this.rawMetrics = {};
    }

    /**
     * Process raw Fabric data.
     */
    transform(rawData) {
        this.rawMetrics = rawData;

        // Extract and normalize each metric
        const velocity = this.normalizeVelocity(rawData.sales_velocity);
        const sentiment = this.normalizeSentiment(rawData.customer_sentiment);
        const latency = this.normalizeLatency(rawData.supply_chain_latency);

        // Apply smoothing
        this.normalizedMetrics.sales_velocity +=
            (velocity - this.normalizedMetrics.sales_velocity) * this.smoothingFactors.sales_velocity;

        this.normalizedMetrics.customer_sentiment +=
            (sentiment - this.normalizedMetrics.customer_sentiment) * this.smoothingFactors.customer_sentiment;

        this.normalizedMetrics.supply_chain_latency +=
            (latency - this.normalizedMetrics.supply_chain_latency) * this.smoothingFactors.supply_chain_latency;

        return this.normalizedMetrics;
    }

    /**
     * Normalize sales velocity (0-100 scale).
     * Fabric data might be in different units (e.g., $, units/hour).
     */
    normalizeVelocity(rawValue) {
        if (!rawValue) return 0;

        // Example: If Fabric returns revenue in thousands
        // Map 0-5000k to 0-100 velocity
        const normalized = Math.min(100, (rawValue / 5000) * 100);
        return constrain(normalized, 0, 100);
    }

    /**
     * Normalize customer sentiment (-1 to 1 scale).
     * Fabric data might be sentiment score (0-100) or NPS (-100 to 100).
     */
    normalizeSentiment(rawValue) {
        if (rawValue === undefined) return 0;

        // If Fabric returns 0-100 sentiment score
        if (rawValue >= 0 && rawValue <= 100) {
            return (rawValue / 50) - 1; // Convert to -1 to 1
        }

        // If already -1 to 1, use directly
        return constrain(rawValue, -1, 1);
    }

    /**
     * Normalize supply chain latency (0-1000ms scale).
     * Fabric data might be in seconds or milliseconds.
     */
    normalizeLatency(rawValue) {
        if (!rawValue) return 0;

        // If Fabric returns latency in seconds, convert to milliseconds
        const milliseconds = typeof rawValue === 'number' && rawValue > 100 ?
            rawValue : rawValue * 1000;

        // Cap at 1000ms
        return constrain(milliseconds, 0, 1000);
    }

    /**
     * Set smoothing factor for specific metric.
     */
    setSmoothingFactor(metric, factor) {
        if (this.smoothingFactors[metric] !== undefined) {
            this.smoothingFactors[metric] = constrain(factor, 0.01, 0.5);
        }
    }
}

// ============================================================================
// FABRIC DATA AGGREGATOR
// ============================================================================

class FabricDataAggregator {
    /**
     * Combine multiple Fabric data streams into single metric update.
     * Useful when metrics come from different Fabric datasets.
     * 
     * THREE-BULLET EDUCATION:
     * 1. Aggregation handles data arriving out-of-order
     * 2. Weights allow certain metrics to have more influence
     * 3. Caching reduces computation for repeated queries
     */
    constructor() {
        this.dataStreams = {};
        this.weights = {
            sales_velocity: 1.0,
            customer_sentiment: 1.0,
            supply_chain_latency: 1.0
        };
        this.lastAggregateTime = 0;
        this.aggregationInterval = 500; // ms
    }

    /**
     * Register a new data stream source.
     */
    registerStream(name, callback) {
        this.dataStreams[name] = {
            callback: callback,
            lastValue: null,
            lastUpdate: 0
        };
    }

    /**
     * Aggregate all data streams.
     */
    async aggregate() {
        const now = Date.now();

        // Prevent overly frequent aggregation
        if (now - this.lastAggregateTime < this.aggregationInterval) {
            return null;
        }

        const aggregated = {
            sales_velocity: 0,
            customer_sentiment: 0,
            supply_chain_latency: 0,
            sources: {}
        };

        let streamCount = 0;

        // Query each stream
        for (const [name, stream] of Object.entries(this.dataStreams)) {
            try {
                const data = await stream.callback();
                if (data) {
                    aggregated.sales_velocity += (data.sales_velocity || 0) * this.weights.sales_velocity;
                    aggregated.customer_sentiment += (data.customer_sentiment || 0) * this.weights.customer_sentiment;
                    aggregated.supply_chain_latency += (data.supply_chain_latency || 0) * this.weights.supply_chain_latency;
                    aggregated.sources[name] = data;
                    streamCount++;
                }
            } catch (error) {
                console.error(`Error aggregating stream "${name}":`, error);
            }
        }

        // Average across streams
        if (streamCount > 0) {
            aggregated.sales_velocity /= streamCount;
            aggregated.customer_sentiment /= streamCount;
            aggregated.supply_chain_latency /= streamCount;
        }

        this.lastAggregateTime = now;
        return aggregated;
    }

    /**
     * Set weight for specific metric.
     */
    setWeight(metric, weight) {
        if (this.weights[metric] !== undefined) {
            this.weights[metric] = weight;
        }
    }
}

// ============================================================================
// ERROR HANDLING & MONITORING
// ============================================================================

class FabricConnectionMonitor {
    /**
     * Monitor Fabric API connection health and performance.
     * 
     * THREE-BULLET EDUCATION:
     * 1. Health checks prevent silent failures
     * 2. Metrics tracking enables performance optimization
     * 3. Alerting system notifies of issues
     */
    constructor(connector) {
        this.connector = connector;
        this.metrics = {
            messagesReceived: 0,
            messagesFailed: 0,
            lastLatency: 0,
            averageLatency: 0,
            connectionUptime: 0,
            lastHealthCheck: null
        };
        this.alerts = [];
        this.healthCheckInterval = null;
    }

    /**
     * Start health monitoring.
     */
    start() {
        this.healthCheckInterval = setInterval(() => this.checkHealth(), 60000); // Every 60s
    }

    /**
     * Stop health monitoring.
     */
    stop() {
        if (this.healthCheckInterval) {
            clearInterval(this.healthCheckInterval);
        }
    }

    /**
     * Perform health check.
     */
    async checkHealth() {
        if (!this.connector.isConnected) {
            this.addAlert('warning', 'Fabric API connection lost');
            return;
        }

        const startTime = Date.now();

        try {
            // Send test ping
            this.connector.send({ type: 'ping' });
            this.metrics.lastLatency = Date.now() - startTime;

            // Update average latency
            this.metrics.averageLatency =
                (this.metrics.averageLatency + this.metrics.lastLatency) / 2;

            // Alert if latency too high
            if (this.metrics.lastLatency > 5000) {
                this.addAlert('warning', `High latency detected: ${this.metrics.lastLatency}ms`);
            }

            this.metrics.lastHealthCheck = new Date();
        } catch (error) {
            this.addAlert('error', `Health check failed: ${error.message}`);
        }
    }

    /**
     * Record message reception.
     */
    recordMessageReceived() {
        this.metrics.messagesReceived++;
    }

    /**
     * Record message failure.
     */
    recordMessageFailed() {
        this.metrics.messagesFailed++;
    }

    /**
     * Add alert to queue.
     */
    addAlert(severity, message) {
        const alert = {
            timestamp: new Date(),
            severity, // 'info', 'warning', 'error'
            message
        };
        this.alerts.push(alert);

        console.log(`[${severity.toUpperCase()}] ${message}`);

        // Keep only last 100 alerts
        if (this.alerts.length > 100) {
            this.alerts.shift();
        }
    }

    /**
     * Get current metrics.
     */
    getMetrics() {
        return { ...this.metrics };
    }

    /**
     * Get recent alerts.
     */
    getAlerts(count = 10) {
        return this.alerts.slice(-count);
    }
}

