## WEBSOCKET REAL-TIME STREAMING

### Architecture: WebSocket → Fabric API → Canvas

```
┌─────────────┐         ┌──────────────┐         ┌─────────────┐
│   Browser   │ <────→  │ Backend API  │ <────→  │   Fabric    │
│  (p5.js)    │ WS      │ (Node.js)    │ REST    │   Service   │
└─────────────┘         └──────────────┘         └─────────────┘
     Canvas                 Auth & Data            Real Metrics
   Visualization           Aggregation           Enterprise Data
```

### Implementation: Node.js Backend

**File: `server.js` (Backend)**

```javascript
// ============================================================================
// KINETIC DATA SYMPHONY - BACKEND SERVER
// Fabric API Integration with WebSocket Streaming
// ============================================================================

const express = require('express');
const cors = require('cors');
const WebSocket = require('ws');
const axios = require('axios');
const jwt = require('jsonwebtoken');
require('dotenv').config();

const app = express();
const PORT = process.env.PORT || 3001;

// ============================================================================
// FABRIC API AUTHENTICATION
// ============================================================================

class FabricAuthManager {
    constructor() {
        this.accessToken = null;
        this.tokenExpiry = 0;
        this.clientId = process.env.FABRIC_CLIENT_ID;
        this.clientSecret = process.env.FABRIC_CLIENT_SECRET;
        this.tenantId = process.env.FABRIC_TENANT_ID;
        this.authority = `https://login.microsoftonline.com/${this.tenantId}`;
    }

    /**
     * Acquire OAuth 2.0 access token using Client Credentials flow.
     * 
     * THREE-BULLET EDUCATION:
     * 1. Client Credentials flow is for backend-to-backend (service principal)
     * 2. Token cached until expiry time to minimize API calls
     * 3. Automatic refresh when token approaches expiration
     */
    async getAccessToken() {
        // Check if cached token is still valid (with 5-minute buffer)
        if (this.accessToken && Date.now() < (this.tokenExpiry - 5 * 60 * 1000)) {
            return this.accessToken;
        }

        try {
            const response = await axios.post(
                `${this.authority}/oauth2/v2.0/token`,
                new URLSearchParams({
                    client_id: this.clientId,
                    client_secret: this.clientSecret,
                    scope: 'https://analysis.windows.net/powerbi/api/.default',
                    grant_type: 'client_credentials'
                }),
                { headers: { 'Content-Type': 'application/x-www-form-urlencoded' } }
            );

            this.accessToken = response.data.access_token;
            this.tokenExpiry = Date.now() + response.data.expires_in * 1000;

            console.log('✅ Fabric API token acquired');
            return this.accessToken;
        } catch (error) {
            console.error('❌ Failed to acquire Fabric token:', error.response?.data || error.message);
            throw error;
        }
    }
}

// ============================================================================
// FABRIC DATA COLLECTOR
// ============================================================================

class FabricDataCollector {
    constructor(authManager) {
        this.auth = authManager;
        this.baseUrl = 'https://api.powerbi.com/v1.0/myorg';
        this.workspaceId = process.env.FABRIC_WORKSPACE_ID;
        this.datasetId = process.env.FABRIC_DATASET_ID;
    }

    /**
     * Fetch real-time metrics from Fabric semantic model.
     * Maps Fabric columns to Kinetic Symphony metrics.
     * 
     * THREE-BULLET EDUCATION:
     * 1. DAX queries execute against semantic model (in-memory analysis engine)
     * 2. Aggregations computed server-side (reduces data transfer)
     * 3. Metric normalization ensures canvas visualization consistency
     */
    async getRealtimeMetrics() {
        try {
            const token = await this.auth.getAccessToken();

            // Query semantic model for aggregated metrics
            const daxQuery = `
                EVALUATE ROW(
                    "TotalSales", SUM([Sales Amount]),
                    "AvgSentiment", AVERAGE([Customer Sentiment Score]),
                    "MedianLatency", MEDIAN([Supply Chain Latency MS]),
                    "TransactionCount", COUNT([Transaction ID]),
                    "TimestampUtc", NOW()
                )
            `;

            const response = await axios.post(
                `${this.baseUrl}/groups/${this.workspaceId}/datasets/${this.datasetId}/querydata`,
                {
                    queries: [{ query: daxQuery }]
                },
                {
                    headers: {
                        'Authorization': `Bearer ${token}`,
                        'Content-Type': 'application/json'
                    }
                }
            );

            // Extract and normalize metrics
            const rawData = response.data.results[0].tables[0].rows[0];
            return this.normalizeMetrics(rawData);
        } catch (error) {
            console.error('❌ Failed to fetch Fabric metrics:', error.message);
            // Return mock data on error for resilience
            return this.getMockMetrics();
        }
    }

    /**
     * Normalize Fabric metrics to Kinetic Symphony scale.
     * Maps enterprise values to visualization range (0-100, -1 to 1, etc).
     */
    normalizeMetrics(rawData) {
        return {
            sales_velocity: this.normalizeValue(
                rawData['TotalSales'],
                0,
                1000000,  // Assumed max daily sales
                0,
                100
            ),
            customer_sentiment: this.normalizeValue(
                rawData['AvgSentiment'],
                -5,        // Sentiment scale: -5 to 5
                5,
                -1.0,
                1.0
            ),
            supply_chain_latency: this.normalizeValue(
                rawData['MedianLatency'],
                0,
                1500,      // Max latency: 1500ms
                0,
                1000
            ),
            transaction_count: rawData['TransactionCount'],
            timestamp: new Date(rawData['TimestampUtc']).getTime()
        };
    }

    /**
     * Map value from source range to target range.
     */
    normalizeValue(value, srcMin, srcMax, tgtMin, tgtMax) {
        const normalized = (value - srcMin) / (srcMax - srcMin);
        return Math.max(tgtMin, Math.min(tgtMax, tgtMin + (normalized * (tgtMax - tgtMin))));
    }

    /**
     * Return mock metrics for development/fallback.
     */
    getMockMetrics() {
        return {
            sales_velocity: Math.random() * 100,
            customer_sentiment: (Math.random() * 2) - 1,
            supply_chain_latency: Math.random() * 1000,
            transaction_count: Math.floor(Math.random() * 10000),
            timestamp: Date.now()
        };
    }
}

// ============================================================================
// WEBSOCKET SERVER FOR BROWSER CLIENTS
// ============================================================================

class KineticWebSocketServer {
    constructor(fabricCollector) {
        this.fabricCollector = fabricCollector;
        this.wss = null;
        this.clients = [];
        this.updateInterval = 1000; // Poll Fabric API every 1 second
        this.updateTimer = null;
    }

    /**
     * Initialize WebSocket server.
     * Accepts browser connections and streams real-time metrics.
     */
    initialize(server) {
        this.wss = new WebSocket.Server({ server });

        this.wss.on('connection', (ws) => {
            console.log(`📡 Client connected (Total: ${this.clients.length + 1})`);
            this.clients.push(ws);

            // Send initial handshake
            ws.send(JSON.stringify({
                type: 'handshake',
                message: 'Connected to Kinetic Data Symphony server',
                timestamp: Date.now()
            }));

            // Handle client messages
            ws.on('message', (message) => {
                try {
                    const data = JSON.parse(message);
                    this.handleClientMessage(ws, data);
                } catch (error) {
                    console.error('Failed to parse WebSocket message:', error);
                }
            });

            // Handle disconnection
            ws.on('close', () => {
                this.clients = this.clients.filter(c => c !== ws);
                console.log(`📴 Client disconnected (Total: ${this.clients.length})`);
            });

            // Handle errors
            ws.on('error', (error) => {
                console.error('WebSocket error:', error);
            });
        });

        // Start metric polling
        this.startMetricPolling();
    }

    /**
     * Broadcast metrics to all connected clients.
     */
    broadcastMetrics(metrics) {
        const message = JSON.stringify({
            type: 'metrics',
            data: metrics,
            timestamp: Date.now()
        });

        this.clients.forEach(client => {
            if (client.readyState === WebSocket.OPEN) {
                client.send(message);
            }
        });
    }

    /**
     * Poll Fabric API and broadcast to clients.
     */
    startMetricPolling() {
        this.updateTimer = setInterval(async () => {
            try {
                const metrics = await this.fabricCollector.getRealtimeMetrics();
                this.broadcastMetrics(metrics);
            } catch (error) {
                console.error('Polling error:', error);
            }
        }, this.updateInterval);
    }

    /**
     * Handle incoming client commands (e.g., visualization mode change).
     */
    handleClientMessage(ws, data) {
        console.log(`📨 Message from client:`, data);
        // Future: Handle client commands, parameter adjustments, etc.
    }

    /**
     * Cleanup: stop polling and close connections.
     */
    shutdown() {
        if (this.updateTimer) clearInterval(this.updateTimer);
        this.wss.close();
        console.log('🔌 WebSocket server shutdown');
    }
}

// ============================================================================
// EXPRESS API ROUTES
// ============================================================================

app.use(cors());
app.use(express.json());
app.use(express.static('public')); // Serve frontend files

