/**
 * Transform Fabric semantic model output to Kinetic metrics.
 * Customizable for different datasets and business logic.
 */

class FabricTransformer {
    constructor(config = {}) {
        this.config = {
            salesDailyMax: config.salesDailyMax || 1000000,
            sentimentScale: config.sentimentScale || 5,
            latencyMaxMs: config.latencyMaxMs || 1500,
            ...config
        };
    }

    /**
     * Transform raw Fabric data to visualization metrics.
     * 
     * THREE-BULLET EDUCATION:
     * 1. Aggregates multiple source columns into single metrics
     * 2. Applies business logic (e.g., weighted sentiment)
     * 3. Handles missing/null data gracefully
     */
    transform(fabricData) {
        return {
            sales_velocity: this.transformSalesVelocity(fabricData),
            customer_sentiment: this.transformSentiment(fabricData),
            supply_chain_latency: this.transformLatency(fabricData),
            health_score: this.calculateHealthScore(fabricData),
            metadata: {
                dataPoints: fabricData.rowCount || 0,
                lastUpdated: Date.now(),
                confidence: this.calculateConfidence(fabricData)
            }
        };
    }

    /**
     * Sales Velocity: Combine transaction count + value + growth rate.
     */
    transformSalesVelocity(data) {
        const value = (data.TotalSales || 0) / this.config.salesDailyMax * 100;
        const count = (data.TransactionCount || 0) / 10000 * 30; // Normalize to 0-30
        const growth = (data.GrowthRate || 0) * 10; // Growth rate weighted

        return Math.min(100, Math.max(0, value + count + growth));
    }

    /**
     * Customer Sentiment: Weighted average of multiple sentiment sources.
     */
    transformSentiment(data) {
        const avgSentiment = (data.AvgSentiment || 0) / this.config.sentimentScale;
        const nlpSentiment = (data.NLPSentimentScore || 0.5) * 2 - 1; // Convert 0-1 to -1 to 1
        const reviewScore = ((data.AvgReviewRating || 3) / 5) * 2 - 1;

        // Weighted average: 50% explicit sentiment + 30% NLP + 20% reviews
        return (avgSentiment * 0.5) + (nlpSentiment * 0.3) + (reviewScore * 0.2);
    }

    /**
     * Supply Chain Latency: Median with percentile analysis.
     */
    transformLatency(data) {
        const medianLatency = data.MedianLatency || 500;
        const p95Latency = data.P95Latency || 800;

        // Use 90th percentile for smoothness (less reactive to outliers)
        const smoothLatency = (medianLatency + p95Latency) / 2;
        return Math.min(1000, Math.max(0, smoothLatency));
    }

    /**
     * Calculate overall health score (0-1).
     * High sales + positive sentiment + low latency = high health.
     */
    calculateHealthScore(data) {
        const salesHealth = Math.min(100, (data.TotalSales || 0) / this.config.salesDailyMax * 100) / 100;
        const sentimentHealth = ((this.transformSentiment(data) + 1) / 2); // Convert -1..1 to 0..1
        const latencyHealth = 1 - (this.transformLatency(data) / 1000); // Inverse (low = good)

        return (salesHealth * 0.4) + (sentimentHealth * 0.35) + (latencyHealth * 0.25);
    }

    /**
     * Data quality score based on null percentage and freshness.
     */
    calculateConfidence(data) {
        const nullRate = (data.nullCount || 0) / (data.rowCount || 1);
        const age = (Date.now() - (data.lastRefresh || Date.now())) / 60000; // Minutes
        const staleness = Math.min(1, age / 60); // Max 1 hour staleness

        return 1 - (nullRate * 0.5 + staleness * 0.5);
    }
}

module.exports = FabricTransformer;
```

