## ERROR HANDLING & RETRY LOGIC

### Resilient API Client

```javascript
/**
 * Fabric API client with exponential backoff & circuit breaker.
 * Handles transient failures gracefully.
 */

class ResilientFabricClient {
    constructor(authManager) {
        this.auth = authManager;
        this.maxRetries = 3;
        this.baseDelay = 1000; // 1 second
        this.circuitBreaker = {
            state: 'CLOSED', // CLOSED, OPEN, HALF_OPEN
            failureCount: 0,
            failureThreshold: 5,
            resetTimeout: 60000 // 1 minute
        };
    }

    /**
     * Fetch with automatic retry on transient failures.
     * Implements exponential backoff: 1s → 2s → 4s
     */
    async fetchWithRetry(url, options = {}, retryCount = 0) {
        // Check circuit breaker
        if (this.circuitBreaker.state === 'OPEN') {
            throw new Error('Circuit breaker OPEN - service temporarily unavailable');
        }

        try {
            const token = await this.auth.getAccessToken();
            const response = await axios.get(url, {
                ...options,
                headers: {
                    'Authorization': `Bearer ${token}`,
                    ...options.headers
                },
                timeout: 10000 // 10 second timeout
            });

            // Reset circuit breaker on success
            this.circuitBreaker.failureCount = 0;
            this.circuitBreaker.state = 'CLOSED';

            return response.data;
        } catch (error) {
            // Determine if error is retryable
            const isRetryable = this.isRetryableError(error);
            const hasRetriesLeft = retryCount < this.maxRetries;

            if (isRetryable && hasRetriesLeft) {
                // Exponential backoff
                const delay = this.baseDelay * Math.pow(2, retryCount);
                console.log(`⏳ Retry attempt ${retryCount + 1} in ${delay}ms`);

                await new Promise(resolve => setTimeout(resolve, delay));
                return this.fetchWithRetry(url, options, retryCount + 1);
            }

            // Circuit breaker: track failures
            this.circuitBreaker.failureCount++;
            if (this.circuitBreaker.failureCount >= this.circuitBreaker.failureThreshold) {
                this.circuitBreaker.state = 'OPEN';
                console.error('🔴 Circuit breaker OPENED due to repeated failures');

                setTimeout(() => {
                    this.circuitBreaker.state = 'HALF_OPEN';
                    this.circuitBreaker.failureCount = 0;
                    console.log('🟡 Circuit breaker HALF_OPEN - attempting recovery');
                }, this.circuitBreaker.resetTimeout);
            }

            throw error;
        }
    }

    /**
     * Determine if error is worth retrying (transient vs permanent).
     */
    isRetryableError(error) {
        if (!error.response) {
            return true; // Network error - likely transient
        }

        const status = error.response.status;
        // Retry on: 408 (timeout), 429 (rate limit), 5xx (server errors)
        return status === 408 || status === 429 || (status >= 500 && status < 600);
    }
}
```

