// In advanced-features.js - Update FabricAPIStreamer

class SecureFabricAPIStreamer {
    constructor(serverUrl = 'ws://localhost:3001') {
        this.serverUrl = serverUrl;
        this.websocket = null;
        this.isConnected = false;
        this.reconnectAttempts = 0;
    }

    /**
     * Connect to backend server (which handles Fabric auth).
     * Browser never directly authenticates with Fabric.
     */
    async connect() {
        return new Promise((resolve, reject) => {
            try {
                this.websocket = new WebSocket(this.serverUrl);

                this.websocket.onopen = () => {
                    console.log('✅ Connected to secure backend server');
                    this.isConnected = true;
                    this.reconnectAttempts = 0;
                    resolve();
                };

                this.websocket.onmessage = (event) => {
                    const data = JSON.parse(event.data);

                    // Validate message origin
                    if (this.validateMessageOrigin(data)) {
                        this.handleMetrics(data);
                    }
                };

                this.websocket.onerror = (error) => {
                    console.error('❌ WebSocket error:', error);
                    reject(error);
                };

                this.websocket.onclose = () => {
                    this.isConnected = false;
                    this.attemptReconnect();
                };
            } catch (error) {
                reject(error);
            }
        });
    }

    /**
     * Validate message to prevent spoofing.
     */
    validateMessageOrigin(data) {
        // Check: type exists, timestamp is recent (< 5 seconds old)
        return data.type && (Date.now() - data.timestamp) < 5000;
    }

    handleMetrics(data) {
        // Update visualization with received metrics
        window.dispatchEvent(new CustomEvent('fabricMetricsReceived', {
            detail: data.data
        }));
    }

    attemptReconnect() {
        if (this.reconnectAttempts < 5) {
            this.reconnectAttempts++;
            const delay = 2000 * Math.pow(1.5, this.reconnectAttempts - 1);
            setTimeout(() => this.connect(), delay);
        }
    }
}
