### 2. Memory Leak Detection

```javascript
// memory-monitor.js

class MemoryMonitor {
    constructor() {
        this.samples = [];
        this.maxSamples = 60; // 1 minute of samples
        this.threshold = 100; // 100MB increase = warning
    }

    /**
     * Record memory usage sample.
     * Run every 1 second to detect leaks.
     */
    recordSample() {
        if (performance.memory) {
            const sample = {
                timestamp: Date.now(),
                usedJSHeapSize: performance.memory.usedJSHeapSize,
                jsHeapSizeLimit: performance.memory.jsHeapSizeLimit
            };

            this.samples.push(sample);
            if (this.samples.length > this.maxSamples) {
                this.samples.shift();
            }

            this.checkForLeaks();
        }
    }

    /**
     * Detect memory leak patterns.
     */
    checkForLeaks() {
        if (this.samples.length < 10) return;

        const oldSample = this.samples[0];
        const newSample = this.samples[this.samples.length - 1];
        const increase = newSample.usedJSHeapSize - oldSample.usedJSHeapSize;

        if (increase > this.threshold) {
            console.warn(`⚠️ Memory increased by ${(increase / 1024 / 1024).toFixed(2)}MB`);
            console.warn('Possible memory leak detected!');
            this.logMemoryStats();
        }
    }

    logMemoryStats() {
        if (performance.memory) {
            const used = (performance.memory.usedJSHeapSize / 1024 / 1024).toFixed(2);
            const limit = (performance.memory.jsHeapSizeLimit / 1024 / 1024).toFixed(2);
            console.log(`Memory: ${used}MB / ${limit}MB`);
        }
    }
}
```

