// performance-profiler.js

class PerformanceProfiler {
    constructor() {
        this.metrics = {};
        this.enabled = true;
    }

    /**
     * Profile function execution time.
     * 
     * THREE-BULLET EDUCATION:
     * 1. Uses performance.now() for microsecond precision
     * 2. Averages multiple runs to reduce noise
     * 3. Helps identify bottlenecks empirically
     */
    profile(name, fn, iterations = 100) {
        const times = [];

        for (let i = 0; i < iterations; i++) {
            const start = performance.now();
            fn();
            const end = performance.now();
            times.push(end - start);
        }

        const avg = times.reduce((a, b) => a + b) / times.length;
        const min = Math.min(...times);
        const max = Math.max(...times);

        this.metrics[name] = { avg, min, max, samples: iterations };

        console.log(`
        Profiling: ${name}
        Average: ${avg.toFixed(3)}ms
        Min: ${min.toFixed(3)}ms
        Max: ${max.toFixed(3)}ms
        `);

        return { avg, min, max };
    }

    /**
     * Generate performance report.
     */
    generateReport() {
        console.table(this.metrics);
    }
}

