### 3. JavaScript Optimization

**Problem:** Event listeners on every frame causes lag.

**Solution: Throttle & Debounce Events**

```javascript
// Throttle mouse movement (fire at most once per 100ms)
class ThrottledMouseListener {
    constructor(throttleTime = 100) {
        this.throttleTime = throttleTime;
        this.lastCall = 0;
        this.lastX = 0;
        this.lastY = 0;
    }

    handleMouseMove() {
        const now = performance.now();
        if (now - this.lastCall >= this.throttleTime) {
            this.lastX = mouseX;
            this.lastY = mouseY;
            this.lastCall = now;

            // Process mouse interaction
            this.applyMouseForce();
        }
    }

    applyMouseForce() {
        // Apply mouse-based forces to particles (expensive operation)
        particleSwarm.particles.forEach(p => {
            const dist = distance(p.x, p.y, this.lastX, this.lastY);
            if (dist < 200) {
                p.ax += (p.x - this.lastX) / 100;
                p.ay += (p.y - this.lastY) / 100;
            }
        });
    }
}

const mouseListener = new ThrottledMouseListener(100);

// In draw loop:
function draw() {
    mouseListener.handleMouseMove();
    // ... rest of render
}
