### 2. Connection Pooling

**Problem:** New Fabric API connections for each request.

**Solution: Connection Pool**

```javascript
// connection-pool.js

class FabricConnectionPool {
    constructor(poolSize = 5) {
        this.poolSize = poolSize;
        this.connections = [];
        this.activeConnections = 0;
        this.waitingQueue = [];
    }

    /**
     * Acquire connection from pool (or create if available).
     * Prevents exhausting API rate limits.
     */
    async acquire() {
        // Return idle connection
        const idleConn = this.connections.find(c => !c.active);
        if (idleConn) {
            idleConn.active = true;
            this.activeConnections++;
            return idleConn;
        }

        // Create new connection if under pool size
        if (this.connections.length < this.poolSize) {
            const newConn = {
                id: this.connections.length,
                active: true,
                createdAt: Date.now(),
                requestCount: 0
            };
            this.connections.push(newConn);
            this.activeConnections++;
            return newConn;
        }

        // Wait for connection to become available
        return new Promise(resolve => {
            this.waitingQueue.push(resolve);
        });
    }

    /**
     * Release connection back to pool.
     */
    release(connection) {
        connection.active = false;
        this.activeConnections--;

        // Service waiting requests
        if (this.waitingQueue.length > 0) {
            const resolve = this.waitingQueue.shift();
            connection.active = true;
            this.activeConnections++;
            resolve(connection);
        }
    }

    /**
     * Get pool statistics for monitoring.
     */
    getStats() {
        return {
            totalConnections: this.connections.length,
            activeConnections: this.activeConnections,
            utilization: this.activeConnections / this.poolSize,
            waitingRequests: this.waitingQueue.length
        };
    }
}
```

