// fabric-queries.js

class OptimizedFabricQueries {
    /**
     * BEFORE (Slow): Multiple aggregations
     * 
     * DEFINE MEASURE Sales[Total] = SUM([Amount])
     * EVALUATE SUMMARIZECOLUMNS(
     *     'Date'[Date],
     *     'Customer'[Region],
     *     'Transaction'[Status],
     *     "Sales", SUM([Amount]),
     *     "Count", COUNTROWS('Transaction'),
     *     "Avg", AVERAGE([Amount])
     * )
     * 
     * Problem: No filtering, evaluates entire dataset (~1000ms)
     */

    /**
     * AFTER (Fast): Filtered + Pre-aggregated
     * 
     * Problem solved:
     * 1. Filter to recent transactions (90% less data)
     * 2. Pre-aggregate at source (reduce memory)
     * 3. Use measure references (cached by Fabric)
     */
    getOptimizedMetricsQuery() {
        return `
            VAR RecentDate = TODAY() - 30  -- Only last 30 days
            RETURN
            ROW(
                "TotalSales", 
                CALCULATE(
                    [Sales],
                    'Date'[Date] >= RecentDate
                ),
                "AvgSentiment", 
                CALCULATE(
                    AVERAGE('Customer'[Sentiment]),
                    'Transaction'[Status] = "Completed"
                )
            )
        `;
    }

    /**
     * Query Result Caching Pattern
     * Store common queries server-side
     */
    getCommonQueries() {
        return {
            // 10-second cache
            realtimeMetrics: {
                query: this.getOptimizedMetricsQuery(),
                cacheTtl: 10000,
                priority: 'HIGH'
            },
            // 1-minute cache
            dailyAggregates: {
                query: `
                    EVALUATE SUMMARIZECOLUMNS(
                        'Date'[Date],
                        "Sales", [Sales],
                        "Transactions", COUNTROWS('Transaction')
