## WEBSOCKET OPTIMIZATION

### 1. Connection Pooling & Message Batching

```javascript
// optimized-websocket.js

class OptimizedWebSocketManager {
    constructor(maxConnections = 1000) {
        this.clients = [];
        this.messageQueue = [];
        this.batchSize = 50;
        this.batchInterval = 50; // ms
        this.maxConnections = maxConnections;
    }

    /**
     * Queue message for batch sending.
     * Reduces context switches in Node.js event loop.
     */
    queueMessage(client, message) {
        this.messageQueue.push({ client, message });

        if (this.messageQueue.length >= this.batchSize) {
            this.flushQueue();
        }
    }

    /**
     * Send all queued messages at once.
     */
    flushQueue() {
        this.messageQueue.forEach(({ client, message }) => {
            if (client.readyState === WebSocket.OPEN) {
                client.send(message);
            }
        });
        this.messageQueue = [];
    }

    /**
     * Monitor connection health.
     */
    startHealthCheck() {
        setInterval(() => {
            this.clients.forEach(client => {
                if (client.isAlive === false) {
                    client.terminate();
                } else {
                    client.isAlive = false;
                    client.ping();
                }
            });
        }, 30000);
    }
}
