### 1. Level of Detail (LOD) System

**Problem:** Complex particles (glow, trails) slow down at scale.

**Solution: Dynamic LOD Based on Performance**

```javascript
// particle-lod.js

class ParticleLOD {
    constructor() {
        this.targetFPS = 60;
        this.currentFPS = 60;
        this.particleCount = 150;
        this.lodLevel = 2; // 0=simple, 1=medium, 2=detailed
    }

    /**
     * Automatically adjust LOD based on FPS.
     * Maintain 60 FPS under all conditions.
     */
    updateLOD(currentFPS) {
        this.currentFPS = currentFPS;

        if (currentFPS < 30) {
            // Performance crisis - reduce to minimum
            this.lodLevel = 0;
            this.particleCount = Math.max(50, this.particleCount * 0.7);
        } else if (currentFPS < 45) {
            // Struggling - reduce quality
            this.lodLevel = 1;
        } else if (currentFPS > 55) {
            // Comfortable - can add quality
            this.lodLevel = 2;
            this.particleCount = Math.min(500, this.particleCount * 1.2);
        }

        console.log(`LOD: Level ${this.lodLevel}, Particles: ${this.particleCount}, FPS: ${currentFPS.toFixed(0)}`);
    }

    /**
     * Render particle with appropriate detail level.
     */
    renderParticle(particle) {
        switch (this.lodLevel) {
            case 0:
                // Minimal: Just filled circle
                fill(hslToRgb(particle.hue, 100, 50, 200));
                noStroke();
                circle(particle.x, particle.y, 4);
                break;

            case 1:
                // Medium: Filled circle + outline
                fill(hslToRgb(particle.hue, 100, 50, 200));
                stroke(hslToRgb(particle.hue, 100, 70, 100));
                strokeWeight(1);
                circle(particle.x, particle.y, 5);
                break;

            case 2:
                // Detailed: Filled + outline + glow
                fill(hslToRgb(particle.hue, 100, 50, 200));
                stroke(hslToRgb(particle.hue, 100, 70, 100));
                strokeWeight(1);
                circle(particle.x, particle.y, 6);

                // Add glow
                noFill();
                stroke(hslToRgb(particle.hue, 100, 70, 50));
                strokeWeight(0.5);
                circle(particle.x, particle.y, 9);
                break;
        }
    }
}
