// ============================================================================
// THE KINETIC DATA SYMPHONY - Core Application Module
// Microsoft Agents League | Track 1 - Generative Enterprise Data Visualization
// ============================================================================

// ============================================================================
// SECTION 1: MOCK FABRIC IQ DATA GENERATOR
// ============================================================================
// This section simulates a real Microsoft Fabric IQ semantic data stream.
// In production, this would connect to actual Fabric APIs via REST/WebSocket.

class FabricIQDataGenerator {
    constructor() {
        // Initialize metric ranges and smoothing factors for realistic data flow
        this.sales_velocity = 0;        // 0-100 (units/time)
        this.customer_sentiment = 0;    // -1.0 to 1.0 (emotional score)
        this.supply_chain_latency = 0;  // 0-1000ms (network delay)

        // Smoothing factors (0.0-1.0) control how quickly metrics change
        // Lower values = smoother, more realistic transitions
        this.smoothing = 0.08;

        // Target values that metrics trend toward each cycle
        this.targets = {
            sales_velocity: 50,
            sentiment: 0.3,
            latency: 250
        };
    }

    /**
     * Update all metrics with smooth interpolation toward random targets.
     * Called every frame to generate realistic data fluctuations.
     */
    update() {
        // Smoothly interpolate sales_velocity toward its target (0-100)
        // This creates organic acceleration/deceleration patterns
        this.sales_velocity += (this.targets.sales_velocity - this.sales_velocity) * this.smoothing;

        // Smoothly interpolate customer_sentiment (-1.0 to 1.0)
        // Sentiment drifts based on simulated customer interactions
        this.customer_sentiment += (this.targets.sentiment - this.customer_sentiment) * this.smoothing;

        // Smoothly interpolate supply_chain_latency (0-1000ms)
        // Latency fluctuates due to network conditions and load
        this.supply_chain_latency += (this.targets.latency - this.supply_chain_latency) * this.smoothing;

        // Randomly update targets every 60-120 frames (creates variation)
        if (frameCount % random(60, 120) === 0) {
            this.targets.sales_velocity = random(20, 95);
            this.targets.sentiment = random(-0.8, 1.0);
            this.targets.latency = random(50, 900);
        }
    }

    /**
     * Export current metrics as a clean data object.
     * Beginner note: This pattern is useful for decoupling data logic from visualization.
     */
    getMetrics() {
        return {
            sales_velocity: constrain(this.sales_velocity, 0, 100),
            customer_sentiment: constrain(this.customer_sentiment, -1.0, 1.0),
            supply_chain_latency: constrain(this.supply_chain_latency, 0, 1000),
            timestamp: Date.now()
        };
    }
}

// ============================================================================
// SECTION 2: PARTICLE SWARM SYSTEM
// ============================================================================
// Advanced particle system that responds to Fabric IQ metrics.
// Each particle is an autonomous agent influenced by environmental data.

class Particle {
    constructor(x, y, metrics) {
        this.x = x;
        this.y = y;
        this.vx = random(-2, 2);  // Velocity X component
        this.vy = random(-2, 2);  // Velocity Y component
        this.ax = 0;               // Acceleration X component
        this.ay = 0;               // Acceleration Y component
        this.mass = random(1, 3);  // Mass affects inertia and visual size
        this.age = 0;              // Particle lifetime tracker
        this.hue = 0;              // HSL Hue value (0-360)
        this.metrics = metrics;    // Reference to current metrics object
    }

    /**
     * Apply forces based on Fabric IQ metrics.
     * This is the "brain" of each particle—it decides how to move.
     * 
     * THREE KEY MAPPINGS:
     * 1. sales_velocity drives particle speed—high sales = fast particles
     * 2. customer_sentiment changes attractors—positive = cohesion, negative = repulsion
     * 3. supply_chain_latency creates jitter—high latency = chaotic movement
     */
    applyForces() {
        // SALES_VELOCITY: Increase base acceleration magnitude
        // Higher sales = more energetic particles
        const velocityMagnitude = map(this.metrics.sales_velocity, 0, 100, 0.5, 3.0);

        // CUSTOMER_SENTIMENT: Sentiment acts as a gravity attractor or repeller
        // Positive sentiment: particles gravitate toward center (unity)
        // Negative sentiment: particles repel from center (chaos)
        const sentimentForce = this.metrics.customer_sentiment * 0.015;
        const centerX = width / 2;
        const centerY = height / 2;
        const distToCenter = dist(this.x, this.y, centerX, centerY);

        if (distToCenter > 0) {
            const angle = atan2(centerY - this.y, centerX - this.x);
            this.ax += cos(angle) * sentimentForce * velocityMagnitude;
            this.ay += sin(angle) * sentimentForce * velocityMagnitude;
        }

        // SUPPLY_CHAIN_LATENCY: High latency creates random jitter/chaos
        // This simulates system degradation and instability
        const latencyJitter = map(this.metrics.supply_chain_latency, 0, 1000, 0.1, 1.2);
        this.ax += random(-latencyJitter * 0.5, latencyJitter * 0.5);
        this.ay += random(-latencyJitter * 0.5, latencyJitter * 0.5);

        // Damping: Friction that prevents particles from accelerating forever
        // This creates natural "settling" behavior
        this.ax *= 0.92;
        this.ay *= 0.92;
    }

    /**
     * Update particle position based on forces and velocity.
     * Classic physics: F=ma, then v+=a, then x+=v
     */
    update() {
        // Apply Verlet integration: position += velocity + acceleration
        this.vx += this.ax;
        this.vy += this.ay;
        this.x += this.vx;
        this.y += this.vy;

        // Increment age for fade-out effect
        this.age += 1;

        // Boundary wrapping: particles that leave screen reappear on opposite side
        // This creates a toroidal space (continuous wrapping)
        if (this.x < -50) this.x = width + 50;
        if (this.x > width + 50) this.x = -50;
        if (this.y < -50) this.y = height + 50;
        if (this.y > height + 50) this.y = -50;

        // Reset acceleration each frame (forces are recalculated)
        this.ax = 0;
        this.ay = 0;
    }

    /**
     * Map Fabric IQ metrics to particle visual properties and render.
     * 
     * THREE-BULLET EDUCATION POINT:
     * 1. Maps sentiment → color palette (warm vs. cool)
     * 2. Maps sales_velocity → particle size and brightness
     * 3. Maps latency → visual opacity/clarity (high latency = ghostly)
     */
    display() {
        // CUSTOMER_SENTIMENT → COLOR PALETTE
        // Negative sentiment (-1): Cool blue/cyan (#00FFFF)
        // Neutral (0): Purple (#FF00FF)
        // Positive (+1): Warm orange/red (#FF6600)
        const normalizedSentiment = (this.metrics.customer_sentiment + 1) / 2; // Convert -1..1 to 0..1
        const hueShift = map(normalizedSentiment, 0, 1, 200, 30); // Hue in HSL
        this.hue = hueShift;

        // SALES_VELOCITY → PARTICLE SIZE
        // Low sales = small particles; high sales = large particles
        const particleSize = map(this.metrics.sales_velocity, 0, 100, 2, 8);

        // SUPPLY_CHAIN_LATENCY → OPACITY (ALPHA)
        // Low latency = clear/opaque; high latency = ghostly/transparent
        const alphaValue = map(this.metrics.supply_chain_latency, 0, 1000, 255, 40);

        // Render particle as glowing circle
        push();
        noStroke();
        fill(hslToRgb(this.hue, 100, 50, alphaValue)); // HSL color with alpha
        circle(this.x, this.y, particleSize);

        // Add glow effect for visual interest
        stroke(hslToRgb(this.hue, 100, 70, alphaValue * 0.3));
        strokeWeight(1);
        noFill();
        circle(this.x, this.y, particleSize * 1.5);
        pop();
    }
}

// ============================================================================
// SECTION 3: PARTICLE SWARM MANAGER
// ============================================================================
// Manages the pool of particles and their collective behavior.

class ParticleSwarm {
    constructor(particleCount = 150) {
        this.particles = [];
        this.particleCount = particleCount;
        this.metrics = null;

        // Initialize particle pool
        for (let i = 0; i < this.particleCount; i++) {
            const x = random(width);
            const y = random(height);
            this.particles.push(new Particle(x, y, {}));
        }
    }

    /**
     * Update swarm with current metrics.
     * Metrics flow through to each particle for independent force calculations.
     */
    update(metrics) {
        this.metrics = metrics;

        // Update each particle independently
        this.particles.forEach(particle => {
            particle.metrics = metrics;  // Share current metrics with particle
            particle.applyForces();      // Calculate forces based on data
            particle.update();           // Update position and velocity
        });
    }

    /**
     * Render all particles to canvas.
     * Called every frame after update.
     */
    display() {
        this.particles.forEach(particle => {
            particle.display();
        });
    }

    /**
     * Optional: Dynamically adjust particle count based on sales_velocity.
     * This creates visual intensity that matches business metrics.
     * Uncomment in main loop if desired.
     */
    adjustParticleCount(targetCount) {
        if (this.particles.length < targetCount) {
            for (let i = this.particles.length; i < targetCount; i++) {
                this.particles.push(new Particle(random(width), random(height), this.metrics));
            }
        } else if (this.particles.length > targetCount) {
            this.particles.splice(targetCount);
        }
    }
}

