// ============================================================================
// FEATURE 1: AUDIO REACTIVITY SYSTEM
// ============================================================================
// Captures microphone input and drives particle behavior via frequency analysis

class AudioReactivityEngine {
    constructor() {
        this.audioContext = null;
        this.analyser = null;
        this.microphone = null;
        this.freqData = new Uint8Array(256);
        this.isActive = false;
        this.audioSensitivity = 1.0; // 0.1 to 3.0 multiplier
        this.frequencyBands = {
            bass: 0,      // 0-50Hz (low energy)
            mid: 0,       // 100-1000Hz (mid energy)
            treble: 0,    // 2000-8000Hz (high energy)
            full: 0       // Overall amplitude
        };
    }

    /**
     * Initialize audio capture from user's microphone.
     * Requires user permission—browser will prompt.
     * 
     * THREE-BULLET EDUCATION:
     * 1. Web Audio API creates audio context for real-time processing
     * 2. getUserMedia() requests microphone access securely
     * 3. AnalyserNode provides fast Fourier transform (FFT) for frequency data
     */
    async initialize() {
        try {
            this.audioContext = new (window.AudioContext || window.webkitAudioContext)();
            const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            this.microphone = this.audioContext.createMediaStreamSource(stream);
            this.analyser = this.audioContext.createAnalyser();
            this.analyser.fftSize = 512; // Fast Fourier Transform size (higher = more precise)

            // Connect audio graph: microphone → analyser
            this.microphone.connect(this.analyser);
            this.isActive = true;

            console.log('✅ Audio reactivity enabled | Microphone initialized');
            return true;
        } catch (error) {
            console.warn('⚠️ Audio access denied:', error.message);
            this.isActive = false;
            return false;
        }
    }

    /**
     * Analyze audio frequencies and extract energy bands.
     * Called every frame to capture real-time audio data.
     */
    update() {
        if (!this.isActive || !this.analyser) return;

        // Get frequency data from analyser (0-255 values for each frequency bin)
        this.analyser.getByteFrequencyData(this.freqData);

        // Extract frequency bands:
        // Frequency bins: ~22Hz per bin (11025Hz / 512 bins)
        // Bass: 0-50Hz = bins 0-2
        // Mid: 100-1000Hz = bins 4-45
        // Treble: 2000-8000Hz = bins 90-360

        const bassSlice = this.freqData.slice(0, 3);
        const midSlice = this.freqData.slice(4, 45);
        const trebleSlice = this.freqData.slice(90, 360);

        // Calculate average for each band
        this.frequencyBands.bass = bassSlice.reduce((a, b) => a + b) / bassSlice.length / 255;
        this.frequencyBands.mid = midSlice.reduce((a, b) => a + b) / midSlice.length / 255;
        this.frequencyBands.treble = trebleSlice.reduce((a, b) => a + b) / trebleSlice.length / 255;
        this.frequencyBands.full = this.freqData.reduce((a, b) => a + b) / this.freqData.length / 255;

        // Apply sensitivity multiplier
        Object.keys(this.frequencyBands).forEach(key => {
            this.frequencyBands[key] *= this.audioSensitivity;
        });
    }

    /**
     * Get current audio energy in 0-1 range.
     * Useful for multiplying particle behaviors.
     */
    getEnergy() {
        return constrain(this.frequencyBands.full, 0, 1);
    }

    /**
     * Shutdown audio stream (cleanup).
     */
    disable() {
        if (this.microphone) {
            this.microphone.disconnect();
            this.microphone.mediaStream.getTracks().forEach(track => track.stop());
        }
        this.isActive = false;
        console.log('🔇 Audio reactivity disabled');
    }
}

// ============================================================================
// FEATURE 2: REAL-TIME API STREAMING (MOCK & WEBSOCKET)
// ============================================================================
// Simulates Microsoft Fabric IQ API integration with optional WebSocket support

class FabricAPIStreamer {
    constructor(useWebSocket = false) {
        this.useWebSocket = useWebSocket;
        this.websocket = null;
        this.isConnected = false;
        this.reconnectAttempts = 0;
        this.maxReconnectAttempts = 5;
        this.reconnectDelay = 2000; // ms between retries
        this.dataBuffer = [];
        this.subscribers = []; // Callback functions for new data
    }

    /**
     * Initialize WebSocket connection to Fabric API.
     * Gracefully falls back to mock data if connection fails.
     * 
     * THREE-BULLET EDUCATION:
     * 1. WebSocket provides bidirectional real-time communication
     * 2. Reconnection logic handles network interruptions automatically
     * 3. Event emitter pattern decouples data source from consumers
     */
    async connect(url = 'wss://fabric-api.microsoft.com/metrics/stream') {
        if (!this.useWebSocket) {
            console.log('📡 WebSocket disabled—using mock data generator');
            return Promise.resolve();
        }

        return new Promise((resolve, reject) => {
            try {
                this.websocket = new WebSocket(url);

                this.websocket.onopen = () => {
                    console.log('✅ WebSocket connected to Fabric API');
                    this.isConnected = true;
                    this.reconnectAttempts = 0;
                    resolve();
                };

                this.websocket.onmessage = (event) => {
                    try {
                        const data = JSON.parse(event.data);
                        this.dataBuffer.push(data);
                        this.notifySubscribers(data);
                    } catch (error) {
                        console.error('Failed to parse WebSocket message:', error);
                    }
                };

                this.websocket.onerror = (error) => {
                    console.error('❌ WebSocket error:', error);
                    this.isConnected = false;
                    reject(error);
                };

                this.websocket.onclose = () => {
                    console.log('⚠️ WebSocket disconnected');
                    this.isConnected = false;
                    this.attemptReconnect();
                };
            } catch (error) {
                reject(error);
            }
        });
    }

    /**
     * Attempt to reconnect with exponential backoff.
     */
    attemptReconnect() {
        if (this.reconnectAttempts < this.maxReconnectAttempts) {
            this.reconnectAttempts++;
            const delay = this.reconnectDelay * Math.pow(1.5, this.reconnectAttempts - 1);
            console.log(`🔄 Reconnecting in ${Math.round(delay / 1000)}s...`);
            setTimeout(() => this.connect(), delay);
        } else {
            console.log('❌ Max reconnection attempts reached. Staying in mock mode.');
        }
    }

    /**
     * Subscribe to incoming data events.
     * Allows multiple listeners to react to new data.
     */
    subscribe(callback) {
        this.subscribers.push(callback);
    }

    /**
     * Notify all subscribers of new data.
     */
    notifySubscribers(data) {
        this.subscribers.forEach(callback => callback(data));
    }

    /**
     * Send command to Fabric API (e.g., change visualization mode).
     */
    send(command) {
        if (this.isConnected && this.websocket) {
            this.websocket.send(JSON.stringify(command));
        } else {
            console.log('📤 Command queued (not connected):', command);
        }
    }

    /**
     * Get recent data history.
     */
    getHistory(maxItems = 100) {
        return this.dataBuffer.slice(-maxItems);
    }

    /**
     * Cleanup: close WebSocket connection.
     */
    disconnect() {
        if (this.websocket) {
            this.websocket.close();
        }
        this.isConnected = false;
    }
}

