// VISUALIZATION MODE: GRID
// ============================================================================
// Data displayed as a responsive grid of cells

class GridMode {
    constructor(gridSize = 12) {
        this.gridSize = gridSize;
        this.cellSize = 0;
        this.grid = [];
        this.initialize();
    }

    /**
     * Initialize grid structure.
     * 
     * THREE-BULLET EDUCATION:
     * 1. Grid cells represent data regions (each cell = metric subset)
     * 2. Cell brightness/color maps to metric value (heatmap)
     * 3. Smooth interpolation creates flowing visual transitions
     */
    initialize() {
        this.cellSize = width / this.gridSize;
        this.grid = [];

        for (let y = 0; y < this.gridSize; y++) {
            const row = [];
            for (let x = 0; x < this.gridSize; x++) {
                row.push({
                    x: x,
                    y: y,
                    value: 0,
                    targetValue: 0
                });
            }
            this.grid.push(row);
        }
    }

    /**
     * Update grid cells based on metrics.
     */
    update(metrics) {
        const normalizedSentiment = (metrics.customer_sentiment + 1) / 2;
        const normalizedVelocity = metrics.sales_velocity / 100;

        this.grid.forEach(row => {
            row.forEach(cell => {
                // Create animation pattern based on cell position
                const distFromCenter = dist(
                    cell.x, cell.y,
                    this.gridSize / 2, this.gridSize / 2
                );

                // Combine sentiment and velocity into target value
                cell.targetValue = normalizedSentiment * normalizedVelocity +
                    (Math.sin(frameCount * 0.05 + distFromCenter) + 1) / 2 * 0.3;

                // Smooth interpolation
                cell.value += (cell.targetValue - cell.value) * 0.1;
            });
        });
    }

    /**
     * Render grid as heatmap.
     */
    display() {
        this.grid.forEach(row => {
            row.forEach(cell => {
                const x = cell.x * this.cellSize;
                const y = cell.y * this.cellSize;

                // Color based on cell value (0-1)
                const hue = map(cell.value, 0, 1, 200, 30); // Blue to red
                const cellColor = hslToRgb(hue, 100, 50, 255);

                fill(cellColor);
                noStroke();
                rect(x, y, this.cellSize - 2, this.cellSize - 2);

                // Border glow for active cells
                if (cell.value > 0.5) {
                    stroke(hslToRgb(hue, 100, 70, 100));
                    strokeWeight(2);
                    noFill();
                    rect(x, y, this.cellSize - 2, this.cellSize - 2);
                }
            });
        });
    }
}

// ============================================================================
// VISUALIZATION MODE: HEXAGON
// ============================================================================
// Data displayed as interconnected hexagonal cells

class HexagonMode {
    constructor(hexSize = 40) {
        this.hexSize = hexSize;
        this.hexagons = [];
        this.initialize();
    }

    /**
     * Initialize hexagonal grid pattern.
     * Hexagons tile efficiently and look more organic than squares.
     */
    initialize() {
        this.hexagons = [];
        const cols = Math.ceil(width / (this.hexSize * 1.5));
        const rows = Math.ceil(height / (this.hexSize * 1.732));

        for (let row = 0; row < rows; row++) {
            for (let col = 0; col < cols; col++) {
                const xOffset = row % 2 === 1 ? this.hexSize * 0.75 : 0;
                const x = col * this.hexSize * 1.5 + xOffset;
                const y = row * this.hexSize * 1.732;

                this.hexagons.push({
                    x: x,
                    y: y,
                    value: 0,
                    targetValue: 0,
                    angle: 0
                });
            }
        }
    }

    /**
     * Update hexagon values based on metrics.
     */
    update(metrics) {
        const velocity = metrics.sales_velocity / 100;
        const sentiment = (metrics.customer_sentiment + 1) / 2;

        this.hexagons.forEach((hex, index) => {
            const distFromMouse = dist(mouseX, mouseY, hex.x, hex.y);
            const influence = Math.max(0, 1 - distFromMouse / 300);

            hex.targetValue = velocity * 0.7 + sentiment * 0.3 + influence * 0.2;
            hex.value += (hex.targetValue - hex.value) * 0.12;
            hex.angle += velocity * 0.02;
        });
    }

    /**
     * Render hexagon grid with animation.
     */
    display() {
        this.hexagons.forEach(hex => {
            push();
            translate(hex.x, hex.y);
            rotate(hex.angle);

            // Draw hexagon
            const size = map(hex.value, 0, 1, this.hexSize * 0.5, this.hexSize);
            const hue = map(hex.value, 0, 1, 200, 30);
            const hexColor = hslToRgb(hue, 100, 50, 200);

            fill(hexColor);
            stroke(hslToRgb(hue, 100, 70, 100));
            strokeWeight(1);

            beginShape();
            for (let i = 0; i < 6; i++) {
                const angle = TWO_PI / 6 * i;
                const x = cos(angle) * size;
                const y = sin(angle) * size;
                vertex(x, y);
            }
            endShape(CLOSE);

            pop();
        });
    }
}

