        this.isOpen = false;
    }

    /**
     * Reset all parameters to initial values.
     */
    resetDefaults() {
        // Reset to original values (shown in constructor)
        window.location.reload();
    }

    /**
     * Get current parameter value.
     */
    getParameter(key) {
        return this.parameters[key]?.value;
    }
}

// ============================================================================
// FEATURE 5: DATA RECORDING & PLAYBACK SYSTEM
// ============================================================================
// Capture and replay visualization sessions for analysis

class DataRecorder {
    constructor() {
        this.isRecording = false;
        this.recordedFrames = [];
        this.playbackIndex = 0;
        this.isPlayingBack = false;
        this.playbackSpeed = 1.0;
    }

    /**
     * Start recording metrics and particle state.
     * 
     * THREE-BULLET EDUCATION:
     * 1. Records metric snapshots every frame (60 fps = high fidelity)
     * 2. Stores particle positions for exact replay (deterministic playback)
     * 3. Compression possible: only record when data changes significantly
     */
    startRecording() {
        this.recordedFrames = [];
        this.isRecording = true;
        console.log('🔴 Recording started');
    }

    /**
     * Add frame data to recording buffer.
     */
    recordFrame(metrics, particleData) {
        if (!this.isRecording) return;

        this.recordedFrames.push({
            timestamp: frameCount,
            metrics: { ...metrics },
            particles: particleData.map(p => ({
                x: p.x,
                y: p.y,
                vx: p.vx,
                vy: p.vy,
                hue: p.hue
            }))
        });
    }

    /**
     * Stop recording and return captured data.
     */
    stopRecording() {
        this.isRecording = false;
        console.log(`⏹️ Recording stopped (${this.recordedFrames.length} frames)`);
        return this.recordedFrames;
    }

    /**
     * Export recorded data as JSON file.
     */
    exportRecording(filename = 'kinetic-recording.json') {
        const dataStr = JSON.stringify(this.recordedFrames, null, 2);
        const blob = new Blob([dataStr], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = filename;
        link.click();
        console.log('📥 Recording exported');
    }

    /**
     * Import recorded data from JSON file.
     */
    importRecording(file) {
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                this.recordedFrames = JSON.parse(e.target.result);
                console.log(`📤 Recording imported (${this.recordedFrames.length} frames)`);
            } catch (error) {
                console.error('Failed to import recording:', error);
            }
        };
        reader.readAsText(file);
    }

    /**
     * Start playback of recorded session.
     */
    startPlayback() {
        this.isPlayingBack = true;
        this.playbackIndex = 0;
        console.log('▶️ Playback started');
    }

    /**
     * Get next frame in playback sequence.
     */
    getPlaybackFrame() {
        if (!this.isPlayingBack || this.recordedFrames.length === 0) return null;

        const frame = this.recordedFrames[Math.floor(this.playbackIndex)];
        this.playbackIndex += this.playbackSpeed;

        if (this.playbackIndex >= this.recordedFrames.length) {
            this.stopPlayback();
        }

        return frame;
    }

    /**
     * Stop playback.
     */
    stopPlayback() {
        this.isPlayingBack = false;
        console.log('⏹️ Playback stopped');
    }

    /**
     * Set playback speed (1.0 = normal, 2.0 = 2x speed, 0.5 = half speed).
     */
    setPlaybackSpeed(speed) {
        this.playbackSpeed = constrain(speed, 0.1, 5.0);
        console.log(`⏱️ Playback speed: ${this.playbackSpeed}x`);
    }
}

// ============================================================================
// FEATURE 6: PLUGIN ARCHITECTURE
// ============================================================================
// Extensible behavior system for custom particle behaviors

class PluginSystem {
    constructor() {
        this.plugins = [];
        this.hooks = {
            onParticleUpdate: [],
            onMetricsChange: [],
            onFrameRender: []
        };
    }

    /**
     * Register a new plugin.
     * Plugins extend particle behavior without modifying core code.
     * 
     * THREE-BULLET EDUCATION:
     * 1. Plugins follow observer pattern (loosely coupled)
     * 2. Multiple plugins can hook same events (composition over inheritance)
     * 3. Plugins enable community extensions (user-created behaviors)
     */
    register(plugin) {
        if (!plugin.name) {
            console.warn('Plugin must have a name property');
            return;
        }

        this.plugins.push(plugin);

        // Register hooks if plugin defines them
        if (plugin.onParticleUpdate) {
            this.hooks.onParticleUpdate.push(plugin.onParticleUpdate.bind(plugin));
        }
        if (plugin.onMetricsChange) {
            this.hooks.onMetricsChange.push(plugin.onMetricsChange.bind(plugin));
        }
        if (plugin.onFrameRender) {
            this.hooks.onFrameRender.push(plugin.onFrameRender.bind(plugin));
        }

        console.log(`✅ Plugin registered: ${plugin.name}`);
    }

    /**
     * Execute all callbacks for a specific hook.
     */
    executeHook(hookName, ...args) {
        if (this.hooks[hookName]) {
            this.hooks[hookName].forEach(callback => callback(...args));
        }
    }

    /**
     * Unregister a plugin.
     */
    unregister(pluginName) {
        this.plugins = this.plugins.filter(p => p.name !== pluginName);
        console.log(`❌ Plugin unregistered: ${pluginName}`);
    }
}

// ============================================================================
// EXAMPLE PLUGIN: Particle Trail System
// ============================================================================
// Demonstrates how to create custom plugins

class TrailPlugin {
    constructor() {
        this.name = 'TrailPlugin';
        this.trails = new Map(); // Store trails for each particle
        this.trailLength = 20;
    }

    /**
     * Hook called when particles update.
     */
    onParticleUpdate(particle, metrics) {
        const particleId = particle.x + '-' + particle.y; // Simple ID

        if (!this.trails.has(particleId)) {
            this.trails.set(particleId, []);
        }

        const trail = this.trails.get(particleId);
        trail.push({ x: particle.x, y: particle.y });

        if (trail.length > this.trailLength) {
            trail.shift();
        }
    }

    /**
     * Hook called during frame rendering.
     */
    onFrameRender() {
        // Draw all trails
        this.trails.forEach(trail => {
            for (let i = 0; i < trail.length - 1; i++) {
                const alpha = map(i, 0, trail.length, 0, 100);
                stroke(0, 212, 255, alpha);
                strokeWeight(1);
                line(trail[i].x, trail[i].y, trail[i + 1].x, trail[i + 1].y);
            }
        });
    }
}

// ============================================================================
// EXAMPLE PLUGIN: Force Field Generator
// ============================================================================
// Creates custom force fields that affect particles

class ForceFieldPlugin {
    constructor() {
        this.name = 'ForceFieldPlugin';
        this.forceFields = [];
    }

    /**
     * Add a custom force field.
     */
    addField(x, y, radius, strength) {
        this.forceFields.push({ x, y, radius, strength });
    }

    /**
     * Apply force fields to particles.
     */
    onParticleUpdate(particle) {
        this.forceFields.forEach(field => {
            const dist = distance(particle.x, particle.y, field.x, field.y);
            if (dist < field.radius) {
                const force = (field.radius - dist) / field.radius * field.strength;
                const angle = atan2(field.y - particle.y, field.x - particle.x);
                particle.ax += cos(angle) * force;
                particle.ay += sin(angle) * force;
            }
        });
    }
}

