// Import advanced features (ensure advanced-features.js is loaded first)
const {
    AudioReactivityEngine,
    FabricAPIStreamer,
    VisualizationModeManager,
    InteractiveControlPanel,
    DataRecorder,
    PluginSystem,
    TrailPlugin,
